# hypothesis: Union expansion over Literal overloads picks one overload per member, so tag on a Literal['a', 'b'] argument is int | str and not bytes.
from typing import Literal, assert_type, overload, reveal_type


@overload
def tag(x: Literal['a']) -> int: ...
@overload
def tag(x: Literal['b']) -> str: ...
@overload
def tag(x: str) -> bytes: ...
def tag(x: str) -> int | str | bytes:
    if x == 'a':
        return 1
    if x == 'b':
        return 'b'
    return x.encode()


def route(key: Literal['a', 'b']) -> int | str:
    result = tag(key)
    reveal_type(result)
    assert_type(tag(key), int | str)
    return result


def fallback(key: str) -> bytes:
    return tag(key)


print(route('a'), route('b'))
print(fallback('zz'))
